import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh } = ctx.THREE;
  const node = new Group();

  // Position, rotation, scale are applied by the adapter; we only set defaults.
  node.position.set(0, 0, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  // ---------- Geometry & Material ----------
  const aspect = 512 / 320; // width / height of atlas region
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  // ---------- Texture Loading ----------
  let loadedTexture = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;
    material.map = tex;
    // Atlas region is at (0,0) with size 512x320; adjust UV repeat to show only that region.
    if (tex.image) {
      const imgW = tex.image.width;
      const imgH = tex.image.height;
      tex.repeat.set(512 / imgW, 320 / imgH);
      tex.offset.set(0, 0);
      tex.needsUpdate = true;
    }
    material.needsUpdate = true;
  });

  // ---------- Mesh ----------
  const mesh = new Mesh(geometry, material);
  // Simple billboard: copy camera quaternion each frame.
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  node.add(mesh);

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Center text on the plane, slightly in front to avoid z‑fighting.
    txt.position.set(0, 0, 0.01);
    node.add(txt);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (fn) {
        const result = fn(node, prim.params ?? {});
        if (result?.cleanup) primitiveCleanups.push(result.cleanup);
        // Store timeline if present for later kill.
        if (result?.timeline) primitiveCleanups.push(() => result.timeline.kill());
      }
    }
  }

  // ---------- User Data & Cleanup ----------
  node.userData.handlers = {};

  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // Kill any GSAP timelines that might have been created elsewhere.
    gsap.globalTimeline.clear();
    // Run primitive cleanups.
    for (const clean of primitiveCleanups) clean();
  };

  return node;
}
